		["{quest:94832}: {npc:2329} at the Lion's Pride Inn in {area:87}; take it only if you'll pass by"] = "{quest:94832} : {npc:2329}, à l'auberge de la Fierté du lion, à {area:87} ; la prendre seulement en cas de passage par là",
		["{quest:96025}: for {npc:254915} at the Summit"] = "{quest:96025} : pour {npc:254915} au sommet",
		["{quest:96145}: for {npc:260825}, later in this guide; keep it"] = "{quest:96145} : pour {npc:260825}, plus loin dans ce guide ; la garder",
		["{quest:96796}: for {npc:249235}, on the way"] = "{quest:96796} : pour {npc:249235}, en chemin",
		["{quest:96830}: for {npc:244512} in {area:16848}, later in this guide; keep it"] = "{quest:96830} : pour {npc:244512} à {area:16848}, plus loin dans ce guide ; la garder",
		["{quest:96833}: for {npc:256222}, the hermit"] = "{quest:96833} : pour {npc:256222}, l'ermite",
		["{quest:96930}: for the {npc:257753}, later in this guide"] = "{quest:96930} : pour le {npc:257753}, plus loin dans ce guide",
		["{quest:96931}: for the {area:17145}, later in this guide"] = "{quest:96931} : pour {area:17145}, plus loin dans ce guide",
		["{quest:96964}: for {npc:259695} in {area:16866}, just ahead"] = "{quest:96964} : pour {npc:259695} à {area:16866}, un peu plus loin",
		["{quest:96991}: for {npc:264795} at the {area:16849}, later in this guide"] = "{quest:96991} : pour {npc:264795} à {area:16849}, plus loin dans ce guide",
	}
	add["forever/alliance/03-loch-modan"] = {
		["No Defias Brotherhood from Wiley (it starts with {npc:234}'s letter in {zone:1436}): skip {zone:1436}. North along the road from {area:87} to {zone:1453}: {npc:466} sits on his horse at the far end of the bridge outside the main gate. Then the gryphons in the {object:2096}, back to {area:69}.\nIf {npc:466} isn't at the arrow, he is walking his horse along the {area:1617} nearby: look along the avenue or wait a moment."] = "Pas de Confrérie défias chez Wiley (elle commence avec la lettre de {npc:234}, dans la {zone:1436}) : pas de passage par la {zone:1436}. Vers le nord par la route, de {area:87} jusqu'à {zone:1453} : {npc:466} est à cheval au bout du pont, devant la grande porte. Puis les griffons du {object:2096}, retour à {area:69}.\nSi {npc:466} n'est pas sous la flèche, il promène son cheval dans la {area:1617}, tout près : regarder le long de l'avenue ou attendre un moment.",
		["On the way to the harbour: {npc:4984}'s message goes to {npc:8997} in {area:442}, beside Terenthis, where the boat lands."] = "En allant au port : le message de {npc:4984} est pour {npc:8997} à {area:442}, à côté de Terenthis, là où le bateau accoste.",
		["{item:253247}: raise it beside Ylva, then hold the spot until {npc:269185} comes"] = "{item:253247} : la planter à côté d'Ylva, puis tenir la position jusqu'à l'arrivée de {npc:269185}",
		["{npc:332} is upstairs in the SI:7 building in {object:2100}: the stairs are hard to see at first. {npc:466} sits on his horse at the far end of the bridge outside the main gate, then back to the gryphons in the {object:2096}.\nIf {npc:466} isn't at the arrow, he is walking his horse along the {area:1617} nearby: look along the avenue or wait a moment."] = "{npc:332} est à l'étage du bâtiment du SI:7, dans la {object:2100} : l'escalier se voit mal au premier abord. {npc:466} est à cheval au bout du pont, devant la grande porte, puis retour aux griffons du {object:2096}.\nSi {npc:466} n'est pas sous la flèche, il promène son cheval dans la {area:1617}, tout près : regarder le long de l'avenue ou attendre un moment.",
	}
	add["forever/alliance/05-duskwood"] = {
		["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters and Bone Chewers (24-27) are the easier kills; Plague Spreaders and Brain Eaters (27-29) drop them too. {npc:522}, an elite, wanders the graves: keep away from him.\nCareful: A {npc:948} casts {spell:3428} as it dies, which brings extra adds.\nCareful: {npc:503} (31) and {npc:771} (32), both rares, haunt the cemetery's north and west, and {npc:1200} (32, elite) keeps to the house at its western edge: leave them be."] = "Chaque goule de la moitié nord du {area:492} peut donner une côte : les Dévoreurs et les Mâcheurs d'os (24-27) sont les plus faciles ; les Répandeurs de peste et les Mangeurs de cervelle (27-29) en donnent aussi. {npc:522}, un élite, erre entre les tombes : rester loin de lui.\nAttention : un {npc:948} lance {spell:3428} en mourant, ce qui fait venir d'autres monstres.\nAttention : {npc:503} (31) et {npc:771} (32), deux rares, hantent le nord et l'ouest du cimetière, et {npc:1200} (32, élite) reste dans la maison à son bord ouest : les laisser tranquilles.",
		["For {npc:1212} in {zone:1453}'s Cathedral, on the walk north"] = "Pour {npc:1212}, à la cathédrale de {zone:1453}, sur la route du nord",
		["For {npc:1217} in {area:150} (the {zone:1437} guide)"] = "Pour {npc:1217} à {area:150} (le guide des {zone:1437})",
		["From level 28: the Skeletal Raiders, Healers and Warders stand in the west part of the {area:492}, just east of {npc:311}'s camp.\nCareful: The Warders are 28-29 and the skeletons stand close together: pull one at a time.\nCareful: {npc:522}, an elite (35), wanders these graves too, and {npc:771} (32, rare) haunts the west part: keep away from both."] = "Dès le niveau 28 : les Écumeurs, les Soigneurs et les Gardiens squelettes se tiennent dans la partie ouest du {area:492}, juste à l'est du camp de {npc:311}.\nAttention : les Gardiens sont de niveau 28-29 et les squelettes sont serrés : les attirer un par un.\nAttention : {npc:522}, un élite (35), erre aussi entre ces tombes, et {npc:771} (32, rare) hante la partie ouest : rester loin des deux.",
		["Head north through Elwynn to {area:1519}; Mathias Shaw is at SI:7 in {object:2100}."] = "Vers le nord à travers Elwynn jusqu'à {area:1519} ; Mathias Shaw est au SI:7, dans la {object:2100}.",
		["North into {area:42}: {npc:276}'s house stands at the east end of town, on the way in."] = "Vers le nord jusqu'à {area:42} : la maison de {npc:276} est au bout est de la ville, à l'entrée.",
		["On into {zone:1453}: {npc:1212} stands in the Cathedral of Light, on the way to the gryphon master. His next quest is for {npc:1217} in {area:150}, where the flight lands."] = "Puis {zone:1453} : {npc:1212} se tient dans la cathédrale de la Lumière, sur le chemin du maître des griffons. Sa quête suivante est pour {npc:1217} à {area:150}, là où le vol arrive.",
		["On into {zone:1453}: {npc:297} (the arrow shows him) takes the letter; the {object:1561} beside him holds the next clue."] = "Puis {zone:1453} : {npc:297} (la flèche le montre) prend la lettre ; la {object:1561} à côté de lui contient l'indice suivant.",
		["On the way west to {npc:311}: Skeletal Fiends and Skeletal Horrors walk the cemetery's southern half, north of {area:94}. {npc:522}, an elite, wanders the graves: keep away from him."] = "En route vers l'ouest jusqu'à {npc:311} : des Démons squelettes et des Squelettes infernaux arpentent la moitié sud du cimetière, au nord de {area:94}. {npc:522}, un élite, erre entre les tombes : rester loin de lui.",
		["Skeletal Raiders"] = "Pillards squelettes",
		["The {npc:511} (26) hides in the small crypt by the {area:121}, south of {area:42}; the glass is inside."] = "{npc:511} (26) se cache dans la petite crypte près du {area:121}, au sud de {area:42} ; le miroir est à l'intérieur.",
		["{item:1946}: the {npc:511}, in the crypt of the cemetery just below"] = "{item:1946} : {npc:511}, dans la crypte du cimetière juste en dessous",
		["{item:910}, from the {object:1560} upstairs"] = "{item:910}, dans le {object:1560} à l'étage",
		["{npc:1212}, in the Cathedral of Light"] = "{npc:1212}, dans la cathédrale de la Lumière",
		["{npc:264}: the Plague Spreaders, with {npc:289}'s ghouls on the next trip west"] = "{npc:264} : les Répandeurs de peste, avec les goules d'{npc:289} au prochain passage à l'ouest",
		["{npc:267}: for {npc:295} in {area:87}, on the walk north to {zone:1453}"] = "{npc:267} : pour {npc:295} à {area:87}, sur la route du nord vers {zone:1453}",
		["{npc:604}, for {quest:58}"] = "{npc:604}, pour {quest:58}",
		["{object:1561}, beside him"] = "{object:1561}, à côté de lui",
		["{quest:177}: the ogres of Vul'Gol, on your {zone:1431} return"] = "{quest:177} : les ogres de Vul'Gol, au prochain passage dans le {zone:1431}",
		["{quest:67}: west from {npc:311}'s camp over the border into {zone:1436} and on to {area:20}, where the {object:3643} stands among the Defias (15-18). Then hearth back to {area:42}."] = "{quest:67} : à l'ouest du camp de {npc:311}, passer la frontière de la {zone:1436} et continuer jusqu'à {area:20}, où le {object:3643} se trouve parmi les Défias (15-18). Puis pierre de foyer pour revenir à {area:42}.",
		["{quest:68}: {npc:267}, in the town hall, takes the footlocker's contents."] = "{quest:68} : {npc:267}, à l'hôtel de ville, prend le contenu du coffre.",
		["{quest:69}: {npc:295} is in {area:87}'s Lion's Pride Inn; the chest with the letter is upstairs."] = "{quest:69} : {npc:295} est à l'auberge de la Fierté du lion, à {area:87} ; le coffre avec la lettre est à l'étage.",
	}
	add["forever/alliance/30-40/01-hillsbrad-foothills"] = {
		["These are elite mobs: grouping up is encouraged, look for people to do it with. The Dragonmaw Reclaimers, Soulbinders and Infiltrators (29-30, elite) camp just east of {npc:270637}."] = "Ce sont des monstres élites : il est conseillé de se grouper, et de chercher des joueurs avec qui y aller. Les Récupérateurs, les Lieurs d'âme et les Infiltrateurs gueule-de-dragon (29-30, élites) campent juste à l'est de {npc:270637}.",
		["back west to {npc:270637}"] = "retour à l'ouest jusqu'à {npc:270637}",
		["for {npc:2700} at {area:320}, in the {zone:1417} guide"] = "pour {npc:2700} au {area:320}, dans le guide des {zone:1417}",
		["{npc:2276}, inside: keep it, the Syndicate camp waits for the road north to Arathi (the {zone:1417} guide)"] = "{npc:2276}, à l'intérieur : la garder, le camp du Syndicat attend la route du nord vers Arathi (le guide des {zone:1417})",
		["{npc:2366}, in the inn: for {area:35} (the {zone:1434} guide)"] = "{npc:2366}, à l'auberge : pour {area:35} (le guide de la {zone:1434})",
		["{npc:270637}: {npc:2094}'s crate, from {area:150}"] = "{npc:270637} : la caisse de {npc:2094}, venue du {area:150}",
		["{npc:5479} trains warriors in {object:2100}, beside the Pig and Whistle. {npc:6236} waits on {area:720} in the {zone:1413}, on the way to {area:392} much later (the 40-50 {zone:1434} guide)."] = "{npc:5479} entraîne les guerriers dans la {object:2100}, près de la taverne du Cochon siffleur. {npc:6236} attend sur l'{area:720}, dans {zone:1413}, sur la route de {area:392}, bien plus tard (le guide 40-50 de la {zone:1434}).",
		["{quest:98291} is a group quest: 16 elite Dragonmaw (29-30) in {area:17716}, just east of {npc:270637}. Skip it if you are alone."] = "{quest:98291} est une quête de groupe : 16 Gueules-de-dragon élites (29-30) à {area:17716}, juste à l'est de {npc:270637}. En solo, la passer.",
	}
	add["forever/alliance/30-40/02-desolace"] = {
		["Back south-east past {npc:11863}'s tower to the Burning Blade's fortress: {npc:5644} hides inside it."] = "Retour au sud-est, après la tour de {npc:11863}, jusqu'à la forteresse de la Lame ardente : {npc:5644} s'y cache.",
		["Back west up the hill to {npc:11863}'s tower with the sceptre, then south along the road to {area:2407}."] = "Retour à l'ouest en remontant la colline jusqu'à la tour de {npc:11863}, avec le sceptre, puis au sud par la route jusqu'à la {area:2407}.",
		["Keep north to {area:598} for {item:15881}: any Slitherblade can drop it. Work the Naga, Sorceresses and Warriors (32-34) of the strand's southern half until it drops.\nCareful: the Myrmidons (34-35) hold the beach's northern half with the Sea Witches and Oracles (34-36, casters), and Tidehunters (36-37) swim off the northern tip: on the way to the chest, keep to the beach and swim straight across."] = "Continuer au nord jusqu'à la {area:598} pour {item:15881} : n'importe quel Ondulame peut la lâcher. Tuer les Nagas, les Sorcières et les Guerriers (32-34) de la moitié sud de la grève jusqu'à ce qu'elle tombe.\nAttention : les Myrmidons (34-35) tiennent la moitié nord de la plage avec les Sorcières des mers et les Oracles (34-36, lanceurs de sorts), et des Chasse-marées (36-37) nagent au large de la pointe nord : pour aller au coffre, rester sur la plage et traverser tout droit à la nage.",
		["North-east from {npc:11596}'s camp to {area:609}, on the way back to {area:608}: every Kolkar drops Centaur Ears for {npc:5752} and {quest:93224} for {npc:5396}. The Magram south-east of {npc:11596}'s camp drop them too, but their village holds Necromancers (42-43) and Guardians (39-41): stay with the Kolkar (30-35)."] = "Au nord-est du camp de {npc:11596}, jusqu'au {area:609}, sur le chemin du retour vers la {area:608} : chaque Kolkar lâche des Oreilles de centaure pour {npc:5752} et des {quest:93224} pour {npc:5396}. Les Magram au sud-est du camp de {npc:11596} en lâchent aussi, mais leur village abrite des Nécromanciens (42-43) et des Gardiens (39-41) : s'en tenir aux Kolkar (30-35).",
		["North-west from {area:609} back along the road to {area:608}: {npc:11438} waits at {area:2407}. He sends you after the robber to {area:35}, where the next guide ends: keep it."] = "Au nord-ouest depuis le {area:609}, retour par la route vers la {area:608} : {npc:11438} attend à la {area:2407}. Il envoie à la poursuite du voleur jusqu'à {area:35}, où finit le guide suivant : la garder.",
		["Use {npc:11596}'s {item:13892} on an Aged, Dying or {npc:4702}: it becomes a tamed kodo that follows you. Walk it back to {npc:11596}'s camp; there, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time; Aged Kodos also drop the hides, and the Scorpashi Lashers that hunt around the graveyard carry the venom. Careful: the Ancient Kodos (36-37) hit hard: tame them, and fight only the Aged Kodos for the hides."] = "Utiliser le {item:13892} de {npc:11596} sur un Vieux kodo, un Kodo mourant ou un {npc:4702} : il devient un kodo apprivoisé qui suit. Le ramener au camp de {npc:11596} ; là, parler au kodo : cela le compte et permet d'apprivoiser le suivant. Cinq kodos, un à la fois ; les Vieux kodos lâchent aussi les peaux, et les Flagellants scorpashi qui chassent autour du cimetière portent le venin. Attention : les Anciens kodos (36-37) frappent fort : les apprivoiser, et ne combattre que les Vieux kodos pour les peaux.",
		["West into the {area:596} first: {npc:11438}'s {object:176751} lie among the skeletons on its western side. Just north of them an {object:417353} starts {quest:79229}, also for {npc:11438}."] = "D'abord à l'ouest, dans le {area:596} : les {object:176751} de {npc:11438} gisent parmi les squelettes, du côté ouest. Juste au nord, {object:417353} lance {quest:79229}, aussi pour {npc:11438}.",
		["West to the shore: the Drysnap Crawlers and Pincers (33-35) on the beach and the clam beds around the wreck carry {item:15878}, about one in seven."] = "À l'ouest, jusqu'au rivage : les Rampants et les Pinceurs Claquesec (33-35) de la plage et les bancs de palourdes autour de l'épave portent {item:15878}, environ un sur sept.",
		["{area:2407} stands by the road south of the fortress, on the way to {npc:11596}'s camp. {npc:11438} collects {object:176751}; they lie among the skeletons of the {area:596}, where {npc:11596}'s kodos are."] = "La {area:2407} se dresse au bord de la route, au sud de la forteresse, sur le chemin du camp de {npc:11596}. {npc:11438} ramasse des {object:176751} ; ils gisent parmi les squelettes du {area:596}, où sont les kodos de {npc:11596}.",
		["{item:13703}, among the skeletons"] = "{item:13703}, parmi les squelettes",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}, sur les nagas Ondulame",
		["{npc:11438}: Tokal waits in {area:35}, at the end of the next guide"] = "{npc:11438} : Tokal attend à {area:35}, à la fin du guide suivant",
		["{npc:11863}: {npc:12369} (38) rises at the {object:177673}, for the south loop at the end of 30-40 (06b): keep it"] = "{npc:11863} : {npc:12369} (38) apparaît à la {object:177673}, pour la boucle sud à la fin de 30-40 (06b) : la garder",
		["{npc:5638}: the satchel lies off the north-west coast, on {zone:1443}'s south loop at the end of 30-40: keep it"] = "{npc:5638} : la sacoche gît au large de la côte nord-ouest, sur la boucle sud de {zone:1443} à la fin de 30-40 : la garder",
		["{object:177787}, beside the chest: its two keys drop only while you have the quest"] = "{object:177787}, à côté du coffre : ses deux clés ne tombent que pendant la quête",
		["{quest:79229}: the {object:417353}"] = "{quest:79229} : {object:417353}",
	}
	add["forever/alliance/30-40/03-ashenvale"] = {
		["Dizzywig's next errand goes back to the {area:2240}, which the route next visits at 45: leave it."] = "La mission suivante de Dizzywig ramène à la {area:2240}, où l'itinéraire repasse au niveau 45 : la laisser.",
		["Down the {area:485} into {zone:1441}. Careful: wait on the platform until the lift is level with it before you step on, and stay on it until it stops; the drop beside it kills. {item:5791} lies a couple of hundred yards north-east of the lift's foot, in {area:2097}, where the Grimtotems (25-27) camp."] = "Descendre par {area:485} jusqu'à {zone:1441}. Attention : attendre sur la plateforme que l'ascenseur soit à sa hauteur avant de monter dessus, et y rester jusqu'à l'arrêt ; la chute à côté est mortelle. {item:5791} se trouve à quelques centaines de mètres au nord-est du pied de l'ascenseur, à la {area:2097}, où campe le Totem sinistre (25-27).",
		["Follow the road north-west out of Theramore to the watchtower at {area:503}, where the road to the {area:403} turns west. Look around the tower: {npc:4967} appears at its foot, and you hand the quest in to him there."] = "Suivre la route vers le nord-ouest en sortant de Theramore, jusqu'à la tour de guet de la {area:503}, où la route de l'{area:403} tourne vers l'ouest. Faire le tour de la tour : {npc:4967} apparaît à son pied, et la quête se rend à lui, sur place.",
		["Follow the road west to the burned inn on the road toward the {zone:1413}: the black shield and Reethe's guard badge lie in the ashes and the hoofprints are in the mud beside the inn."] = "Suivre la route vers l'ouest jusqu'à l'auberge incendiée, sur la route des {zone:1413} : le bouclier noir et l'insigne de garde de Reethe gisent dans les cendres, et les traces de sabots sont dans la boue à côté de l'auberge.",
		["From Theramore follow the road north-west through the marsh into the {zone:1413} and up the coast to {area:392}: Stranglethorn starts at {area:35}, across the sea. {area:392}'s gryphon master stands above the dock; {npc:3391} is upstairs in the house above it; {quest:1111} waits on the dock by the boat."] = "Depuis Theramore, suivre la route vers le nord-ouest à travers le marais jusqu'aux {zone:1413}, puis remonter la côte jusqu'à {area:392} : Strangleronce commence à {area:35}, de l'autre côté de la mer. Le maître des griffons de {area:392} se tient au-dessus du quai ; {npc:3391} est à l'étage de la maison au-dessus ; {quest:1111} attend sur le quai, près du bateau.",
		["Take Tervosh's next errand now: he stands here only right after the hand-in. {npc:4966} waits for the next {zone:1445} visit, at about 39."] = "Prendre tout de suite la mission suivante de Tervosh : il ne se tient ici que juste après le rendu. {npc:4966} attend la prochaine visite au {zone:1445}, vers le niveau 39.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:12866} stands by the entrance of {area:1316}, a few hundred yards north-east of the top of the {area:485}; the Razorfen Battleguards, Thornweavers and Death's Head Cultists (33-34, elite) hold the thorny slopes around her. Skip it if you are alone."] = "Ce sont des monstres élites : il est conseillé de se grouper, et de chercher des joueurs avec qui la faire. {npc:12866} se tient près de l'entrée des {area:1316}, à quelques centaines de mètres au nord-est du haut de {area:485} ; les Gardes de guerre, les Tisseurs d'épines de Tranchebauge et les Sectateurs de la Tête de Mort (33-34, élites) tiennent les pentes épineuses autour d'elle. En solo, la passer.",
		["Vimes's next errand, The Deserters, is for the {zone:1445} visit at 39: leave it."] = "La mission suivante de Vimaire, Les déserteurs, est pour la visite au {zone:1445} au niveau 39 : la laisser.",
		["West to the wyverns' cliffs at {area:482}. Every wyvern there can drop a venom sac."] = "À l'ouest, jusqu'aux falaises des wyvernes, au {area:482}. Toutes les wyvernes peuvent y lâcher un sac de venin.",
		["{item:5791}: for {npc:4048}, just past {area:482}"] = "{item:5791} : pour {npc:4048}, juste après {area:482}",
		["{npc:3391}: for {npc:4631}, on {area:35}'s dock where the boat lands"] = "{npc:3391} : pour {npc:4631}, sur le quai de {area:35}, où le bateau accoste",
		["{npc:4048} camps north of {area:482}, just over the border into {zone:1444} on the path up to {area:489}: hand him the journal. His next quest is inside {area:1717}: leave it."] = "{npc:4048} campe au nord du {area:482}, juste après la frontière de {zone:1444}, sur le sentier qui monte à {area:489} : lui remettre le journal. Sa quête suivante se passe dans le {area:1717} : la laisser.",
		["{npc:4452}: for {quest:1111} on {area:392}'s dock, where this guide ends"] = "{npc:4452} : pour {quest:1111} sur le quai de {area:392}, où ce guide se termine",
		["{npc:4456} is in the north of town, Captain Vimes and {npc:4948} on the top floor of {area:514}; {npc:4941} stands in the town."] = "{npc:4456} est dans le nord de la ville, le capitaine Vimaire et {npc:4948} au dernier étage de la {area:514} ; {npc:4941} se tient dans la ville.",
		["{npc:4630}: for {npc:3391} in {area:392}, on the way to the boat"] = "{npc:4630} : pour {npc:3391} à {area:392}, en chemin vers le bateau",
		["{npc:4964}: {area:503} is the watchtower on the road west, next"] = "{npc:4964} : {area:503} est la tour de guet sur la route de l'ouest, l'étape suivante",
		["{npc:4967}, at the foot of the tower"] = "{npc:4967}, au pied de la tour",
		["{npc:4967}: {npc:4966} holds {area:504}, for the {zone:1445} visit at 39"] = "{npc:4967} : {npc:4966} tient la {area:504}, pour la visite au {zone:1445} au niveau 39",
		["{object:19868} lies all over the flats. Scorpid Reavers and Salt Flats Scavengers roam the north half, Sparkleshell Tortoises (30-31) the middle of the flats: hunt them for the shells. Careful: Sparkleshell Snappers (34-35) wander the whole flats, and the Saltstone Gazers (34-35) and Scorpid Terrors (33-34) hold the far south: leave them and keep to the north half.\nCareful: {npc:5935} (37, rare) roams the south-east of the flats, around 83-88,71-84: leave it be."] = "Les {object:19868} jonchent les Salines. Les Scorpides ravageurs et les Charognards des Salines errent dans la moitié nord, les Tortues nacrétoiles (30-31) au milieu des Salines : les chasser pour les carapaces. Attention : les Mordeuses nacrétoiles (34-35) errent dans toutes les Salines, et les Contemplateurs du sel gemme (34-35) et les Scorpides terrifiants (33-34) tiennent l'extrême sud : les laisser et rester dans la moitié nord.\nAttention : {npc:5935} (37, rare) rôde au sud-est des Salines, vers 83-88,71-84 : le laisser tranquille.",
		["{object:21042}: for Captain Vimes, on the way back through Theramore"] = "{object:21042} : pour le capitaine Vimaire, au retour par Theramore",
		["{quest:1111}: for {npc:3945} in {area:35}, where the boat lands"] = "{quest:1111} : pour {npc:3945} à {area:35}, où le bateau accoste",
		["{quest:1111}: {quest:1039}, from {npc:8026} in {zone:1457}"] = "{quest:1111} : {quest:1039}, de {npc:8026} à {zone:1457}",
	}
	add["forever/alliance/30-40/04-stranglethorn-vale"] = {
		["Keep it for another visit: {npc:729} (37) prowls the Lashtail hill."] = "La garder pour une autre visite : {npc:729} (37) rôde sur la colline des raptors flagellants.",
		["{npc:250660}'s next errand sends you into the Venture Co. house at {area:37}, among Venture Co. Agents (39): leave it."] = "La mission suivante de {npc:250660} envoie dans la maison de la KapitalRisk, au {area:37}, parmi des Venture Co. Agents (39) : la laisser.",
		["{npc:3945}, on the dock"] = "{npc:3945}, sur le quai",
		["{npc:3945}: for {npc:267} in {area:42}, where the second Stranglethorn loop starts"] = "{npc:3945} : pour {npc:267} à {area:42}, où commence la deuxième boucle de Strangleronce",
		["{npc:4631} stands on the dock where the boat lands. Bind your hearthstone at the inn: it is your way back here from the north of the jungle at the end of the loop."] = "{npc:4631} se tient sur le quai où le bateau accoste. Lier la pierre de foyer à l'auberge : c'est le moyen de revenir ici depuis le nord de la jungle, à la fin de la boucle.",
		["{npc:4631}, on the dock"] = "{npc:4631}, sur le quai",
		["{npc:4631}: for {npc:2496}, upstairs in the tavern"] = "{npc:4631} : pour {npc:2496}, à l'étage de la taverne",
	}
	add["forever/alliance/30-40/04b-stranglethorn-vale"] = {
		["Check the hilltop on your way to the raptors. If {npc:729} isn't here or you can't pull her alone, keep moving; {npc:717} can take the paw on the later visit."] = "Jeter un œil au sommet de la colline en allant vers les raptors. Si {npc:729} n'y est pas ou ne peut pas être attirée en solo, continuer ; {npc:717} peut prendre la patte lors de la visite suivante.",
		["East from the ruins, hunt Lashtail Raptors around the hill south-west of Nesingwary's camp. If you have {quest:187}, are at least 36 and see {npc:729} (37) alone, you can take her paw here or leave the hunt for your next visit."] = "À l'est des ruines, chasser les Raptors flagellants autour de la colline au sud-ouest du camp de Nesingwary. Avec {quest:187}, au niveau 36 ou plus, et {npc:729} (37) seule en vue, il est possible de prendre sa patte ici, ou de laisser la chasse pour la visite suivante.",
		["Hand the paw to {npc:717} beside Hemet."] = "Remettre la patte à {npc:717}, à côté d'Hemet.",
		["{item:4600}, from {npc:2832}"] = "{item:4600}, chez {npc:2832}",
		["{npc:215643}, whom Bibbly sent you to find, waits by the {object:56910}. He asks for a {item:4600}: {npc:2832} sells it in the tavern, a few steps away."] = "{npc:215643}, que Bibbly a demandé de retrouver, attend près de {object:56910}. Il demande un {item:4600} : {npc:2832} en vend à la taverne, à quelques pas.",
		["{npc:267} works in {area:42}'s town hall, a short walk from the flight master; {npc:661} stands just east of it."] = "{npc:267} travaille à l'hôtel de ville de {area:42}, à quelques pas du maître de vol ; {npc:661} se tient juste à l'est.",
		["{npc:661}: the evidence lies in the {area:121}, on the next guide's way to the {zone:1435}: keep it"] = "{npc:661} : la preuve se trouve dans le {area:121}, sur le chemin du guide suivant vers le {zone:1435} : la garder",
		["{npc:715}, if the first Stranglethorn loop didn't give it: the Lashtail Raptors, after the jungle ruins"] = "{npc:715}, si la première boucle de Strangleronce ne l'a pas donnée : les Raptors flagellants, après les ruines de la jungle",
		["{npc:717}. Keep it for the later visit if you skip {npc:729} on the raptor hill."] = "{npc:717}. La garder pour la visite suivante si {npc:729} est laissée de côté sur la colline des raptors.",
		["{npc:729} (37) prowls the hilltop."] = "{npc:729} (37) rôde au sommet de la colline.",
		["{npc:729} on the raptor hill"] = "{npc:729} sur la colline des raptors",
		["{npc:729}'s hill"] = "La colline de {npc:729}",
		["{npc:770}, if the first Stranglethorn loop didn't give it: for {npc:773} in {area:35}"] = "{npc:770}, si la première boucle de Strangleronce ne l'a pas donnée : pour {npc:773} à {area:35}",
	}
	add["forever/alliance/30-40/05-arathi-highlands"] = {
		["For characters of 36 to 38. {area:327}, where the naga and the professor's water elementals are 38-40, is a group stop: skip it if you are alone."] = "Pour les personnages de niveau 36 à 38. {area:327}, où les nagas et les élémentaires d'eau du professeur sont de niveau 38-40, est une étape de groupe : en solo, la passer.",
		["His next errand goes to {zone:1457}, off this route: leave it."] = "Sa mission suivante mène à {zone:1457}, hors de cet itinéraire : la laisser.",
		["Leave the {zone:2548} for about level 41: its Western Front has elite patrols. After Stranglethorn, the {zone:2548} guide takes you from {zone:1455} to {area:69}, then through {area:2417}."] = "Laisser {zone:2548} pour le niveau 41 environ : son Front occidental a des patrouilles élites. Après Strangleronce, le guide de {zone:2548} mène d'{zone:1455} à {area:69}, puis par le {area:2417}.",
		["South from {area:318}, past {area:314}, to {area:317} in the hills: the Witch Doctors stand among the huts and the Shadow Hunters guard the far end of the valley. Every troll can drop a tusk. Careful: Witherbark Goliaths (35, elite) walk the far end with the Shadow Hunters: pull the Hunters out to you one at a time, away from the Goliaths."] = "Au sud de la {area:318}, après la {area:314}, jusqu'au {area:317}, dans les collines : les Sorciers-docteurs se tiennent parmi les huttes et les Chasseurs des ombres gardent le fond de la vallée. Tous les trolls peuvent lâcher une défense. Attention : des Witherbark Goliaths (35, élites) circulent au fond avec les Chasseurs des ombres : attirer les Chasseurs un par un vers soi, loin des Goliaths.",
		["South from {area:42} to the {area:121}, on the way to {zone:1430}: the mound of dirt by the Nightbane worgen (29-31) holds the evidence {npc:661} wants."] = "Au sud de {area:42}, jusqu'au {area:121}, en route vers le {zone:1430} : le monticule de poussière près des worgens Plaie-de-nuit (29-31) contient la preuve que veut {npc:661}.",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay.\nCareful: the charts and logs lie deep inside the wrecks: watch your breath bar and come up between them; a water breathing potion makes it easy."] = "Les deux épaves gisent dans la baie à l'ouest de la crique. Les cartes et les journaux de bord sont à l'intérieur ; les gemmes reposent sur le fond autour d'elles. Des nagas Daguéchine nagent dans toute la baie.\nAttention : les cartes et les journaux sont au fond des épaves : surveiller la jauge de souffle et remonter respirer entre deux ; une potion de respiration aquatique facilite la tâche.",
		["the {object:19030}"] = "le {object:19030}",
		["{npc:2276}, inside, if the {zone:1424} guide didn't take it: the Syndicate camp is on the way to Arathi"] = "{npc:2276}, à l'intérieur, si le guide des {zone:1424} ne l'a pas prise : le camp du Syndicat est sur la route d'Arathi",
		["{npc:2700}: {npc:1075}'s plea, from the {zone:1437}"] = "{npc:2700} : la supplique de {npc:1075}, venue des {zone:1437}",
		["{npc:661}, in {area:42}"] = "{npc:661}, à {area:42}",
	}
	add["forever/alliance/30-40/06-badlands"] = {
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map and {npc:269577}'s mining helmet lie among their tents. Tunnelers and Darkweavers carry Ryedol's pick and {npc:269577}'s artifacts. Crag Coyotes roam the slopes around it. Careful: Shadowforge Ruffians (36-37, elite) walk among them, most on the slopes between the pass and the camp: pull the Tunnelers and Darkweavers away from them."] = "Les nains Ombreforge campent juste au nord du site de fouilles ; la carte froissée et le casque de mineur de {npc:269577} sont parmi leurs tentes. Les Tunneliers et les Tisseurs d'ombre portent la pioche de Ryedol et les artefacts de {npc:269577}. Des Coyotes des rochers rôdent sur les pentes alentour. Attention : des Forbans Ombreforge (36-37, élites) circulent parmi eux, surtout sur les pentes entre le col et le camp : attirer les Tunneliers et les Tisseurs d'ombre loin d'eux.",
	}
	add["forever/alliance/30-40/06b-desolace"] = {
		["The Slitherblade naga hold the north-west coast north of {npc:11863}'s tower, on the shore and out in the water. Karnitol's satchel drops now and then from their Tidehunters and Sea Witches, most of them underwater ({spell:131} helps): take it if it comes, it is optional. Any naga can drop Rackmore's golden key. Swim out to {area:2406} off the far northern tip and use the {item:15766} on the {object:177673}: {npc:12369} (38) rises; kill him for the {quest:6027}."] = "Les nagas Ondulame tiennent la côte nord-ouest, au nord de la tour de {npc:11863}, sur le rivage et dans l'eau. La sacoche de Karnitol tombe de temps en temps sur leurs Chasse-marées et leurs Sorcières des mers, la plupart sous l'eau ({spell:131} aide) : la prendre si elle tombe, elle est facultative. N'importe quel naga peut lâcher la clé d'or de Rackmore. Nager jusqu'à l'{area:2406}, au large de la pointe nord, et utiliser la {item:15766} sur la {object:177673} : {npc:12369} (38) surgit ; le tuer pour {quest:6027}.",
		["{npc:11438}, if the first {zone:1443} visit didn't give it"] = "{npc:11438}, si la première visite en {zone:1443} ne l'a pas donnée",
		["{npc:11863}, if the first {zone:1443} visit didn't give it"] = "{npc:11863}, si la première visite en {zone:1443} ne l'a pas donnée",
		["{npc:11863}, if the first {zone:1443} visit didn't take the sceptre back to him"] = "{npc:11863}, si la première visite en {zone:1443} ne lui a pas rapporté le sceptre",
		["{npc:5396}, if the first {zone:1443} visit didn't give it"] = "{npc:5396}, si la première visite en {zone:1443} ne l'a pas donnée",
		["{npc:5638}, if the first {zone:1443} visit didn't take it: the wreck lies below {npc:11863}'s tower"] = "{npc:5638}, si la première visite en {zone:1443} ne l'a pas prise : l'épave se trouve sous la tour de {npc:11863}",
		["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons.\nCareful: Rexxar (62, elite), the Horde's champion, walks the road past the graveyard with his bear Misha and attacks Alliance players: when he comes by, step well away from the road and let him pass."] = "{npc:6019} se tient au bord du {area:596}, au sud-ouest de la {area:2407} ; des {object:176751} gisent parmi les squelettes.\nAttention : Rexxar (62, élite), le champion de la Horde, parcourt la route qui longe le cimetière avec son ourse Misha et attaque les joueurs de l'Alliance : quand il passe, s'éloigner bien de la route et le laisser passer.",
		["{object:177787}, if the first {zone:1443} visit didn't take it"] = "{object:177787}, si la première visite en {zone:1443} ne l'a pas pris",
	}
	add["forever/alliance/40-50/01-stranglethorn-vale"] = {
		["\"Sea Wolf\" MacKinley, on the top floor, offers {quest:2872} from level 40 (under 40, this guide's last {area:35} stop offers it again)."] = "« Loup de mer » MacKinley, au dernier étage, propose {quest:2872} à partir du niveau 40 (sous le niveau 40, le dernier arrêt de ce guide à {area:35} la propose de nouveau).",
		["\"Sea Wolf\" MacKinley: for Stoley in {zone:1446}, keep it"] = "« Loup de mer » MacKinley : pour Stoley à {zone:1446}, la garder",
		["Already have all eight Tumbled Crystals? Hand them to {npc:737} now."] = "Déjà les huit Cristaux réduits ? Les remettre maintenant à {npc:737}.",
		["Back down to town: Shaky stands at the tunnel mouth; {npc:2488} and MacKinley are on the top floor."] = "Retour en ville : Shaky se tient à l'entrée du tunnel ; {npc:2488} et MacKinley sont au dernier étage.",
		["Back east along the road to Theramore: {npc:4944} takes the deserters' news on the top floor of {area:514}, and the flight master stands by its gate."] = "Retour vers l'est par la route jusqu'à Theramore : {npc:4944} reçoit les nouvelles des déserteurs au dernier étage de la {area:514}, et le maître de vol se tient près de sa porte.",
		["Back to Theramore for the boat to {area:150}."] = "Retour à Theramore pour le bateau du {area:150}.",
		["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye: take them from the Raiders and Mages (39-41) at the Bloodsail camp on the beach just north of town, where you found the letter. Leave the {area:43} camp south of town (Warlocks and Swashbucklers 41-43) for the level-48 visit.\nCareful: Rippa (44, a rare crocolisk) swims the shore beside the camp: stay out of the water."] = "Tous les membres de la Voile sanglante lâchent du tabac à priser et l'un d'eux porte l'œil de {npc:2493} : les prendre sur les Écumeurs et les Mages (39-41) du camp de la Voile sanglante, sur la plage juste au nord de la ville, là où la lettre a été trouvée. Laisser le camp de {area:43} au sud de la ville (Démonistes et Bretteurs 41-43) pour la visite au niveau 48.\nAttention : Rippa (44, un crocilisque rare) nage le long du rivage à côté du camp : rester hors de l'eau.",
		["Fly to {area:392}"] = "Prendre un vol pour {area:392}",
		["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it.\nIf {quest:1265} isn't done yet: {npc:4967} waits at the foot of the tower once you have looked around. Hand the quest in to him there, not in Theramore, and take his next errand on the spot."] = "Suivre la route vers le nord-ouest en sortant de Theramore, jusqu'à la tour de guet de la {area:503}. Des Creuseuses Rochefange parcourent le marais alentour.\nSi {quest:1265} n'est pas encore faite : {npc:4967} attend au pied de la tour une fois les alentours examinés. Lui rendre la quête sur place, pas à Theramore, et prendre aussitôt sa mission suivante.",
		["Follow the road south-east from Biggs to the pass into the {zone:1419}, keeping clear of {area:75}, the Horde town to the north-east.\nDown the pass, the road bends east to {area:1438}. Careful: {npc:5982} vultures (46) and Starving Snickerfangs (45) hunt in the dry hills south of the road: stay on it and keep moving."] = "Suivre la route vers le sud-est depuis Biggs jusqu'au col des {zone:1419}, à l'écart de {area:75}, la ville de la Horde au nord-est.\nAu bas du col, la route tourne vers l'est jusqu'au {area:1438}. Attention : des vautours {npc:5982} (46) et des Raillecrocs affamées (45) chassent dans les collines sèches au sud de la route : rester dessus et ne pas s'arrêter.",
		["From the Bloodsail camp, climb into the Mistvale hills just east of it: the Elder Mistvale Gorillas (40) there drop the giblets."] = "Depuis le camp de la Voile sanglante, grimper dans les collines de Valbrume juste à l'est : les Anciens gorilles de Valbrume (40) y lâchent les abats.",
		["Head south from the compound to {area:37}. The Venture Co. Geologists in the shore camps carry the Tumbled Crystals; Venture Co. Agents (39) walk among them. Stay on the shore: stealthed Shadowmaw Panthers prowl the jungle south and east of the lake."] = "Au sud depuis le camp retranché, jusqu'au {area:37}. Les Géologues de la KapitalRisk, dans les camps du rivage, portent les Cristaux réduits ; des Venture Co. Agents (39) circulent parmi eux. Rester sur le rivage : des Panthères Ombregueule camouflées rôdent dans la jungle au sud et à l'est du lac.",
		["If you didn't take {quest:2872} on the earlier stop: \"Sea Wolf\" MacKinley, on the top floor."] = "Si {quest:2872} n'a pas été prise lors de l'arrêt précédent : « Loup de mer » MacKinley, au dernier étage.",
		["Into the {zone:1419}"] = "Vers les {zone:1419}",
		["MacKinley's Voodoo Dues waits for the level-48 {area:35} stop, with Zanzil's village: leave it for now."] = "Les Gages vaudou de MacKinley attendent l'arrêt au niveau 48 à {area:35}, avec le village de Zanzil : les laisser pour l'instant.",
		["Seahorn's next task, {quest:597}, waits for the level-48 {area:35} stop with the {area:43} camp (41-43): leave it for now."] = "La tâche suivante de Seahorn, {quest:597}, attend l'arrêt au niveau 48 à {area:35}, avec le camp de {area:43} (41-43) : la laisser pour l'instant.",
		["The boat to {area:35} leaves from {area:392}'s dock, below the flight master. Without the {area:392} flight path: follow the road west out of the marsh into the {zone:1413} and north up the coast to {area:392}, and learn it there."] = "Le bateau pour {area:35} part du quai de {area:392}, sous le maître de vol. Sans le trajet aérien de {area:392} : suivre la route vers l'ouest, hors du marais, jusque dans les {zone:1413}, puis remonter la côte vers le nord jusqu'à {area:392}, et l'y apprendre.",
		["The crystals gathered at {area:37}"] = "Les cristaux ramassés au {area:37}",
		["The pass to the {zone:1419}"] = "Le col des {zone:1419}",
		["The road to {area:1438}"] = "La route du {area:1438}",
		["You missed this on the route's earlier visit here: take it now, before the Bloodsail camp. Its gorillas live on the hills just above the camp."] = "Étape manquée lors du passage précédent de l'itinéraire : la prendre maintenant, avant le camp de la Voile sanglante. Ses gorilles vivent sur les collines juste au-dessus du camp.",
		["for {area:1438}, just south of the swamp"] = "pour {area:1438}, juste au sud du marais",
		["{area:720} lies off the {area:391} just south of {area:392}: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "L'{area:720} se trouve au large de {area:391}, juste au sud de {area:392} : traverser à gué les hauts-fonds du banc de sable. {npc:6236} envoie quatre adversaires puis {npc:6238} (niveau 33), un à la fois.",
		["{item:216617}, in the supply crate deep in the cave"] = "{item:216617}, dans la caisse de ravitaillement au fond de la grotte",
		["{npc:217412}: {quest:93176}, from the {zone:1417} guide"] = "{npc:217412} : {quest:93176}, du guide des {zone:1417}",
		["{npc:2494}' Akiris by the Bundle waits for the level-48 {area:35} stop (its naga are 43-44): leave it for now."] = "De derrière les fagots, de {npc:2494}, attend l'arrêt au niveau 48 à {area:35} (ses nagas sont de niveau 43-44) : la laisser pour l'instant.",
		["{npc:2498}'s Zanzil's Secret waits for the same stop (Zanzil's village is 43-44): leave it for now."] = "Le secret de Zanzil, de {npc:2498}, attend le même arrêt (le village de Zanzil est de niveau 43-44) : la laisser pour l'instant.",
		["{npc:5385} is upstairs in the keep and {npc:5393} inside it; the gryphon master stands south of the keep."] = "{npc:5385} est à l'étage du donjon et {npc:5393} à l'intérieur ; le maître des griffons se tient au sud du donjon.",
		["{npc:6236}'s Affray first: {area:720} lies just south of {area:392}. The boat to {area:150} leaves from Theramore afterwards."] = "D'abord La Dispute, de {npc:6236} : l'{area:720} se trouve juste au sud de {area:392}. Le bateau pour le {area:150} part ensuite de Theramore.",
		["{npc:717}, beside the other hunters"] = "{npc:717}, à côté des autres chasseurs",
		["{npc:737}: the Tumbled Crystals, at {area:37} on the northern loop"] = "{npc:737} : les Cristaux réduits, au {area:37}, sur la boucle nord",
	}
	add["forever/alliance/40-50/01b-riverglades"] = {
		["Before the second wave: its raiders (44-45), bombardiers (43-44) and {quest:95124}'s ships after them (45) are more than a level over you below 44. Top up on the first camp's buccaneers and musketeers (41-43) at its south-west end, away from the port. {npc:259758}, a rare elite of level 49, roams these cliffs: if you see him, keep well away. Or, with a group, run the {area:1517} dungeon instead."] = "Avant la deuxième vague : ses pillards (44-45), ses bombardiers (43-44) et, après eux, les navires de {quest:95124} (45) ont plus d'un niveau d'avance sous le niveau 44. Compléter sur les boucaniers et les mousquetaires (41-43) du premier camp, à son extrémité sud-ouest, loin du port. {npc:259758}, un élite rare de niveau 49, rôde sur ces falaises : s'il est en vue, rester bien à l'écart. Ou, en groupe, faire plutôt le donjon d'{area:1517}.",
		["Careful: the Western Front is written for level 44 and up. Its Twilight Champions are 43-44 and its Thralls 44, Twilight Enforcers (elites, 45) patrol through the camps, and {npc:256881} (46, elite) is for a group only. Below 44, top up on the Eastsea pirates by the port first, or come back with a friend."] = "Attention : le Front occidental est prévu pour le niveau 44 et plus. Ses Champions du Crépuscule sont de niveau 43-44 et ses Esclaves 44, des Massacreurs du Crépuscule (élites, 45) patrouillent dans les camps, et {npc:256881} (46, élite) est réservé à un groupe. Sous le niveau 44, compléter d'abord sur les pirates des mers de l'Est près du port, ou revenir avec un ami.",
		["Claire is in the cave under the eastern edge of {area:16723}: its entrance is at 50.0,46.0."] = "Claire est dans la grotte sous le bord est de {area:16723} : l'entrée est en 50.0,46.0.",
		["Level 44 on the Eastsea pirates"] = "Niveau 44 sur les pirates des mers de l'Est",
		["North from {area:16724}, past {area:16729} and across the river, to {area:16723}, the farm town the Twilight cult holds; keep clear of {area:16743}, the Horde's fort east of the town. {npc:259158} the kobold waits in a cage at the arrow, {npc:256831} below ground in a cave at the town's eastern edge (the entrance is at 50.0,46.0), and {npc:258697} waits at his farm on the north-eastern edge."] = "Au nord depuis {area:16724}, après {area:16729} et de l'autre côté de la rivière, jusqu'à {area:16723}, le bourg agricole que tient le culte du Crépuscule ; rester à l'écart de {area:16743}, le fort de la Horde à l'est du bourg. {npc:259158}, le kobold, attend dans une cage à la flèche, {npc:256831} sous terre, dans une grotte au bord est du bourg (l'entrée est en 50.0,46.0), et {npc:258697} attend à sa ferme, au bord nord-est.",
		["Out to the pirates' cliffs once more. Plant Whizzbuzz's charges on the three ships moored below the camp, south to north. {quest:95124} (level 45) walks the middle ship's top deck; her loot chest is below deck. Keep an eye out for {npc:259758} on the way."] = "Retour aux falaises des pirates. Poser les charges de Whizzbuzz sur les trois navires amarrés sous le camp, du sud au nord. {quest:95124} (niveau 45) arpente le pont supérieur du navire du milieu ; son coffre de butin est dans la cale. Surveiller {npc:259758} en chemin.",
		["the Wanted poster"] = "l'avis de recherche",
		["{npc:259158}: {quest:94961}, in his cage"] = "{npc:259158} : {quest:94961}, dans sa cage",
		["{npc:260026} waits beside the road east of the pass.\nThis guide is written for levels 41-45: the route comes here at about 41, after {zone:1434}. The port's second wave and the Western Front's camps in the north are 43-45, with elite Twilight Enforcers (45) on patrol and {npc:256881} (46, elite) for groups only: below 41, do Stranglethorn first."] = "{npc:260026} attend au bord de la route, à l'est du col.\nCe guide est écrit pour les niveaux 41-45 : l'itinéraire arrive ici vers 41, après la {zone:1434}. La deuxième vague du port et les camps du Front occidental, au nord, sont de niveau 43-45, avec des Massacreurs du Crépuscule élites (45) en patrouille et {npc:256881} (46, élite), pour les groupes seulement : sous le niveau 41, faire d'abord Strangleronce.",
	}
	add["forever/alliance/40-50/03-feralas"] = {
		["Only with the distress beacon, a rare drop in {zone:1444}: it starts a quest to find the robot it calls for."] = "Seulement avec la balise de détresse, un butin rare en {zone:1444} : elle lance une quête pour retrouver le robot qu'elle appelle.",
		["The robot sits in a small cave on the north side of {area:1105}, just north-west of the ruins. Escort it to the dock on the {area:1108}, where the boat to Feathermoon leaves; its reward waits with {npc:7406} in {area:35}, on the {zone:1425} guide's {area:35} stop.\nCareful: Three ambushes spawn during the escort, and the robot warns you before each one. The first is 3 yetis, just after the robot leaves the cave and climbs toward the road. The second is 3 gorillas, on the path that runs along the cliff. The third is about 4 gnolls, one of them a caster, where the route turns off toward the dock."] = "Le robot est dans une petite grotte au nord du {area:1105}, juste au nord-ouest des ruines. L'escorter jusqu'au quai de {area:1108}, d'où part le bateau de Plumelune ; sa récompense attend chez {npc:7406}, à {area:35}, lors de l'arrêt à {area:35} du guide des {zone:1425}.\nAttention : trois embuscades surgissent pendant l'escorte, et le robot prévient avant chacune. La première, 3 yétis, juste après la sortie de la grotte, quand le robot monte vers la route. La deuxième, 3 gorilles, sur le sentier qui longe la falaise. La troisième, environ 4 gnolls, dont un lanceur de sorts, là où le chemin bifurque vers le quai.",
		["for {npc:7771} at the {area:1938} in {zone:1446}: keep it"] = "pour {npc:7771} au {area:1938}, à {zone:1446} : la garder",
		["{npc:3936}: {quest:4267}, for {npc:7740} on the {zone:1446} guide's {zone:1457} stop: keep it"] = "{npc:3936} : {quest:4267}, pour {npc:7740}, lors de l'arrêt à {zone:1457} du guide de {zone:1446} : la garder",
		["{npc:7900} in {area:1116} sends you to {npc:7771} at the {area:1938} in {zone:1446}, where the {zone:1446} guide stops for his dig."] = "{npc:7900}, au {area:1116}, envoie voir {npc:7771} au {area:1938}, à {zone:1446}, où le guide de {zone:1446} s'arrête pour sa fouille.",
	}
	add["forever/alliance/40-50/04-tanaris"] = {
		["Only if a Southsea pirate gave you a {item:9250}: it starts a quest for {npc:7882}, inside, where you stand."] = "Seulement si un pirate des Mers du sud a lâché {item:9250} : cela lance une quête pour {npc:7882}, à l'intérieur, ici même.",
		["The little turtle {npc:5955} wanders the west edge of the {quest:3362}, most often where the arrow leads: take him from the edge and leave the Thistleshrubs (48-50) alone. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "La petite tortue {npc:5955} erre le long du bord ouest de {quest:3362}, le plus souvent là où mène la flèche : la prendre depuis le bord et laisser les Chardonniers (48-50) tranquilles. La ramener chez sa femme {npc:6015}, au bord de l'eau juste à l'est de {area:977} : elle avance lentement et les bêtes du désert l'attaquent, la garder en vie.",
		["The {area:2240} lies on the {area:439} in south-east {zone:1441}: {npc:4454} is in the gnomes' camp beside the track, {npc:4630} and {npc:4709} by the goblins' camp. With {quest:1137} handed in, {npc:4630} has work: {npc:4630} first, then {npc:4709}, who runs off to keep Rizzle busy; then take Rizzle's plans from the gnomes' camp and bring them back to {npc:4630}."] = "La {area:2240} se trouve sur {area:439}, au sud-est des {zone:1441} : {npc:4454} est dans le camp des gnomes près de la piste, {npc:4630} et {npc:4709} près du camp des gobelins. Une fois {quest:1137} rendue, {npc:4630} a du travail : {npc:4630} d'abord, puis {npc:4709}, qui part occuper Rizzle ; ensuite, prendre les plans de Rizzle dans le camp des gnomes et les rapporter à {npc:4630}.",
		["{npc:7771}: the {item:10556} is in {area:392}, on the Un'Goro guide's flight to {area:976}, which hands it in here: keep it"] = "{npc:7771} : le {item:10556} se trouve à {area:392}, sur le vol du guide d'Un'Goro vers {area:976}, qui la rend ici : la garder",
		["{npc:7771}: {quest:3380}, from Angelas in Feathermoon"] = "{npc:7771} : {quest:3380}, d'Angelas, à Plumelune",
	}
	add["forever/alliance/40-50/05-the-hinterlands"] = {
		["Group quest: {quest:348} ends at {npc:1449} in Mistvale. Hand him ten gorilla fangs and he calls three waves of gorillas (41-42), one after another, then {npc:1514} (44). In players' recordings, 12 of the 27 people who started it died there. Take it if you have a friend or two along."] = "Quête de groupe : {quest:348} se termine chez le {npc:1449}, à Valbrume. Lui remettre dix crocs de gorille : il appelle trois vagues de gorilles (41-42), l'une après l'autre, puis {npc:1514} (44). Dans les enregistrements des joueurs, 12 des 27 personnes qui l'ont commencée y sont mortes. La prendre avec un ou deux amis.",
		["Only if you escorted the {zone:1425} robot: {npc:7406} has its reward too."] = "Seulement si le robot des {zone:1425} a été escorté : {npc:7406} a aussi sa récompense.",
		["Only if you escorted the {zone:1444} robot: its reward waits with {npc:7406} here in {area:35}."] = "Seulement si le robot de {zone:1444} a été escorté : sa récompense attend chez {npc:7406}, ici à {area:35}.",
		["Only with the distress beacon, a rare drop in the {zone:1425}: it starts a quest to find the robot it calls for."] = "Seulement avec la balise de détresse, un butin rare dans les {zone:1425} : elle lance une quête pour retrouver le robot qu'elle appelle.",
		["The Vilebranch Soothsayers (46-47) walk the ground around the foot of the {area:355}: their totems are for Maret Firetend, and more Vilebranch Totems lie on the ground among them: pick those up too. Careful: {npc:7996} and {npc:8636} (50, elites) stand on the altar's south-east side: take the Soothsayers on its west side, away from them, and stay off the altar."] = "Les Devins Vilebranch (46-47) parcourent le terrain au pied de l'{area:355} : leurs totems sont pour Maret Gardefeu, et d'autres Totems vilebranche gisent au sol parmi eux : les ramasser aussi. Attention : {npc:7996} et {npc:8636} (50, élites) se tiennent du côté sud-est de l'autel : attaquer les Devins du côté ouest, loin d'elles, et rester hors de l'autel.",
		["The robot sits at the head of the river west of {area:351}. Escort it east to the shore beyond the {area:307}, then ride back west for {area:348}; its reward waits with {npc:7406} in {area:35}, later in this guide.\nCareful: Two ambushes spawn during the escort: first three wildkin owlbeasts, then three trolls. Before each, the robot halts and announces it senses danger. Oozes, stealthed wolves and a large turtle along the path can join fights, and they respawn even if cleared beforehand."] = "Le robot se trouve à la source de la rivière, à l'ouest du {area:351}. L'escorter vers l'est jusqu'au rivage, après {area:307}, puis revenir vers l'ouest jusqu'au {area:348} ; sa récompense attend chez {npc:7406}, à {area:35}, plus loin dans ce guide.\nAttention : deux embuscades surgissent pendant l'escorte : d'abord trois chouettards, puis trois trolls. Avant chacune, le robot s'arrête et annonce qu'il sent un danger. Des limons, des loups camouflés et une grande tortue le long du chemin peuvent se joindre aux combats, et ils réapparaissent même s'ils ont été éliminés avant.",
		["for {quest:2990} at {area:1438}: the {zone:1428} guide hands it in"] = "pour {quest:2990} au {area:1438} : le guide des {zone:1428} la rend",
		["{item:3925}, from {npc:2536}"] = "{item:3925}, de {npc:2536}",
		["{item:4457}: in your bags already if you cook"] = "{item:4457} : déjà dans les sacs pour un cuisinier",
		["{npc:1494} comes only for his food: hand in {quest:619} at Captain Smotts' ruined lifeboat on the shore south-east of {area:35}, with 10 Barbecued Buzzard Wings and 5 {item:4595}, and he comes to the boat. {npc:2832}, the food and drink vendor at the inn, sells the wine. The wings are a cook's dish: if you don't cook, bring them from the Auction House."] = "{npc:1494} ne vient que pour sa nourriture : rendre {quest:619} au canot de survie accidenté du capitaine Smotts, sur la rive au sud-est de {area:35}, avec 10 Ailes de busard grillées et 5 {item:4595}, et il vient jusqu'au canot. {npc:2832}, le marchand de nourriture et de boissons de l'auberge, vend le vin. Les ailes sont un plat de cuisine : sans le métier de cuisinier, les acheter à l'hôtel des ventes.",
		["{npc:1494}'s bait"] = "L'appât de {npc:1494}",
		["{npc:2486}, beside the inn"] = "{npc:2486}, à côté de l'auberge",
		["{npc:2486}, by the inn"] = "{npc:2486}, près de l'auberge",
		["{npc:2535} and Jon-Jon"] = "{npc:2535} et Jon-Jon",
		["{object:2289}: the food goes in, {npc:1494} comes"] = "{object:2289} : la nourriture y va, {npc:1494} arrive",
	}
	add["forever/alliance/40-50/06-searing-gorge"] = {
		["Careful: Slavers can net you and call allies within 15 yards. A Taskmaster or Steamsmith may be standing beside one. Wait for a clear pull or leave the pack; don't descend into the Cauldron for this bounty."] = "Attention : les Esclavagistes peuvent jeter un filet et appeler des alliés dans un rayon de 15 mètres. Un Sous-chef ou un Forge-vapeur peut se tenir à côté. Attendre une occasion d'attirer proprement ou laisser le groupe ; ne pas descendre dans le Chaudron pour cette prime.",
		["Culling the Competition"] = "Culling the Competition",
		["Dark Iron Slavers"] = "Esclavagistes Sombrefer",
		["Dark Iron Steamsmiths at the surface furnaces carry Thorium Plated Daggers as well as the {item:18959}. Pull from the outside of the camp."] = "Les Forge-vapeur Sombrefer des fourneaux de surface portent des Dagues plaquées en thorium en plus de la {item:18959}. Attirer depuis l'extérieur du camp.",
		["Dark Iron Taskmasters"] = "Sous-chefs Sombrefer",
		["Still under level 48.66 after the {area:1443} (a solo player usually is; a group's Culling the Competition or {quest:7701} covers it)? Top up on the Incendosaurs (47) in the {area:1443}'s lava pools, pulled to the edge.\nCareful: {npc:14621} (50, elite) and his elite guards hold the {area:1443}'s depths: keep to the pools near the entrance and don't follow the tunnels in."] = "Toujours sous le niveau 48.66 après {area:1443} (c'est souvent le cas en solo ; en groupe, Culling the Competition ou {quest:7701} suffit) ? Compléter sur les Incendosaures (47) des bassins de lave de {area:1443}, attirés vers le bord.\nAttention : {npc:14621} (50, élite) et ses gardes élites tiennent le fond de {area:1443} : rester près des bassins de l'entrée et ne pas suivre les tunnels.",
		["Still under level 48.98 (a solo player usually is; a group's {quest:3452} covers it)? Top up on the Searing Lava Spiders (47-48) of the western plateaus, away from the {object:147516} camps.\nCareful: Magma Elementals (46-48) drift among the spiders: pull one at a time. Keep south of the Twilight camp at {area:1442}, whose cultists are elites."] = "Toujours sous le niveau 48.98 (c'est souvent le cas en solo ; en groupe, {quest:3452} suffit) ? Compléter sur les Araignées de lave incendiaires (47-48) des plateaux de l'ouest, loin des camps {object:147516}.\nAttention : des Élémentaires de magma (46-48) dérivent parmi les araignées : les attirer un par un. Rester au sud du camp du Crépuscule de la {area:1442}, dont les sectateurs sont des élites.",
		["Take the bounty from the board only if you want to hunt the linked dwarf packs with a group."] = "Ne prendre la prime du tableau que pour chasser en groupe les nains, qui se tiennent en paquets liés.",
		["The Steamsmiths at the furnaces carry the {item:18959}; the Lookouts on the southern ridges carry the Spyglass. Keep the {item:11818} if a dwarf drops it."] = "Les Forge-vapeur des fourneaux portent la {item:18959} ; les Guetteurs des crêtes du sud portent la longue-vue. Garder la {item:11818} si un nain la lâche.",
		["The Twilight elites of {npc:8436}'s camp drop the {quest:3378} page, about one in five: keep the group together here until one drops."] = "Les élites du Crépuscule du camp de {npc:8436} lâchent la page de {quest:3378}, environ une fois sur cinq : garder le groupe ici jusqu'à ce qu'elle tombe.",
		["The furnaces and southern ridges"] = "Les fourneaux et les crêtes du sud",
		["Thorium Plated Daggers"] = "Dagues plaquées en thorium",
		["With your group, look for Taskmasters on the open ledges. Stay on the surface; don't follow the arrow into the {area:1443}."] = "Avec le groupe, chercher les Sous-chefs sur les corniches à découvert. Rester en surface ; ne pas suivre la flèche dans {area:1443}.",
		["grind on {npc:5858}"] = "tuer en boucle : {npc:5858}",
		["{quest:3378}: the page"] = "{quest:3378} : la page",
	}
	add["forever/alliance/40-50/07-un-goro-crater"] = {
		["Fly to {area:392}"] = "Prendre un vol pour {area:392}",
		["For characters of 49 to 50, but most quests here are level 51-53: on purpose, for their experience. This first visit keeps to the crater's eastern half, where the beasts are 48-52, so pull them one at a time; the pylons, the bones and the hive wait for the later Un'Goro visit at about 54."] = "Pour les personnages de niveau 49 à 50, mais la plupart des quêtes ici sont de niveau 51-53 : c'est voulu, pour leur expérience. Cette première visite se limite à la moitié est du cratère, où les bêtes sont de niveau 48-52 : les attirer une par une ; les pylônes, les ossements et la ruche attendent la visite suivante d'Un'Goro, vers le niveau 54.",
		["For {npc:7740} in {zone:1457}, on the {zone:1448} guide's {zone:1457} stop: keep it"] = "Pour {npc:7740} à {zone:1457}, lors de l'arrêt à {zone:1457} du guide de {zone:1448} : la garder",
		["On the ride south, {npc:7771}'s dig camp stands at the {area:1938}: hand him the {item:10556}."] = "En descendant vers le sud, le camp de fouilles de {npc:7771} se trouve au {area:1938} : lui remettre le {item:10556}.",
		["Still short of level 50 after the refuge's hand-ins? The next guide opens in {zone:1455} with quests that need level 50: top up on the Bloodpetal Lashers and Threshers (48-50) of the eastern jungle, where you took the petals, before you leave the crater."] = "Toujours sous le niveau 50 après les rendus du refuge ? Le guide suivant commence à {zone:1455} par des quêtes qui demandent le niveau 50 : compléter sur les Flagellants et les Batteurs Pétale-de-sang (48-50) de la jungle de l'est, là où les pétales ont été ramassés, avant de quitter le cratère.",
		["The flight lands in {area:976}."] = "Le vol atterrit à {area:976}.",
		["The gorillas on {area:1943} carry the pelts: keep it for the second Un'Goro visit, around 54"] = "Les gorilles du {area:1943} portent les peaux : la garder pour la deuxième visite d'Un'Goro, vers le niveau 54",
		["{npc:7771}'s next task, Into the Depths, is inside the {area:1417}: skip it."] = "La tâche suivante de {npc:7771}, Dans les profondeurs, se passe dans le {area:1417} : la passer.",
		["{npc:7771}'s {item:10556} stands in {area:392}: fly there first, then on to {area:976}."] = "Le {item:10556} de {npc:7771} se trouve à {area:392} : y aller d'abord en vol, puis continuer jusqu'à {area:976}.",
		["{npc:9272}, {npc:9271}, {npc:9270} and {npc:9618} have quests among mobs of 51-55: leave them for the later Un'Goro visit, at about 54."] = "{npc:9272}, {npc:9271}, {npc:9270} et {npc:9618} ont des quêtes parmi des monstres de niveau 51-55 : les laisser pour la visite suivante d'Un'Goro, vers le niveau 54.",
		["{quest:3444} stands on the hill just south-west of the flight master."] = "{quest:3444} se trouve sur la colline juste au sud-ouest du maître de vol.",
	}
	add["forever/alliance/50-60/02-felwood"] = {
		["Portal to {zone:1438}"] = "Portail vers {zone:1438}",
	}
	add["forever/alliance/50-60/03-winterspring"] = {
		["Fly to {area:392}"] = "Prendre un vol pour {area:392}",
		["{npc:7771}'s next task, Into the Depths, is inside the {area:1417}: skip it."] = "La tâche suivante de {npc:7771}, Dans les profondeurs, se passe dans le {area:1417} : la passer.",
		["{quest:3444} stands on the hill just south-west of the flight master."] = "{quest:3444} se trouve sur la colline juste au sud-ouest du maître de vol.",
	}
	t.guides = type(t.guides) == "table" and t.guides or {}
	for id, list in pairs(add) do
		local g = t.guides[id]
		if type(g) ~= "table" then
			g = {}
			t.guides[id] = g
		end
		for en, fr in pairs(list) do
			if g[en] == nil or g[en] == "" then g[en] = fr end
		end
	end
end
